compile.workshop:
variables {
    global:
        0: A
        1: g
        2: i
}

subroutines {
    0: sub
}

rule ("optimized") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.g == 2;
    }
    actions {
        Set Global Variable(g, 3);
        If(Compare(Global.g, ==, 2));
            Set Global Variable(g, 6);
        End;
        Set Global Variable(g, 12);
        If(Compare(Global.g, ==, 2));
            Set Global Variable(g, 1);
        End;
        Create HUD Text(All Players(All Teams), Global.A, Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
        Create HUD Text(All Players(All Teams), Global.A, Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
        Wait(0.016, Ignore Condition);
        For Global Variable(i, 1, 5, 1);
            Set Global Variable(g, Global.i);
        End;
    }
}

//Optimizations disabled
rule ("disabled") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.g == Add(1, 1);
    }
    actions {
        Set Global Variable(g, Add(1, 2));
        If(Compare(Global.g, ==, Add(1, 1)));
            Set Global Variable(g, Multiply(2, 3));
        End;
        Set Global Variable(g, Add(Multiply(3, 4), 0));
        If(Compare(Global.g, ==, Add(1, 1)));
            Set Global Variable(g, 1);
        End;
        Create HUD Text(All Players(All Teams), Add(Global.A, 0), Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
        Create HUD Text(All Players(All Teams), Multiply(Global.A, 1), Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
    }
}

rule ("Subroutine sub") {
    event {
        Subroutine;
        sub;
    }
    actions {
        If(Compare(Global.g, ==, Add(1, 1)));
            Set Global Variable(g, 1);
        End;
    }
}

//Optimizations enabled
//Strict optimizations enabled
rule ("strict") {
    event {
        Ongoing - Global;
    }
    actions {
        Create HUD Text(All Players(All Teams), Add(Global.A, 0), Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
        Create HUD Text(All Players(All Teams), Multiply(Global.A, 1), Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
        Set Global Variable(g, 5);
    }
}

//Strict optimizations disabled
//Optimize for size enabled
rule ("size") {
    event {
        Ongoing - Global;
    }
    actions {
        Wait(False, Ignore Condition);
        For Global Variable(i, 1, 5, True);
            Set Global Variable(g, Global.i);
        End;
    }
}

